CREATE TABLE mail_send_requests_copy_0601 AS SELECT request_id, organization_id, project_id, idempotency_key, request_sha256, recipient_sha256, content_sha256, state, provider_started_at, provider_message_id, requested_at, updated_at, mail_provider, mail_domain_id, mail_binding_revision, effective_from, effective_reply_to, request_input_sha256 FROM mail_send_requests;
CREATE TABLE mail_send_events_copy_0601 AS SELECT provider_event_id, organization_id, project_id, request_id, provider_message_id, event_type, outcome, detail_sha256, occurred_at, sent_at, received_at, reputation_kind FROM mail_send_events;
CREATE TABLE mail_reputation_states_copy_0601 AS SELECT organization_id, project_id, state, warmup_started_at, suspended_at, suspension_reason, triggering_event_id, version, updated_at FROM mail_reputation_states;
CREATE TABLE mail_send_outcomes_copy_0601 AS SELECT organization_id, project_id, request_id, outcome, provider_event_id, occurred_at, version, updated_at FROM mail_send_outcomes;
CREATE TABLE mail_reputation_decisions_copy_0601 AS SELECT decision_id, organization_id, project_id, action, reason, triggering_event_id, eligible_send_count, hard_bounce_count, complaint_count, actor_id, evidence_sha256, occurred_at FROM mail_reputation_decisions;
DROP TABLE mail_reputation_decisions;
DROP TABLE mail_send_outcomes;
